character_book.description:
{
  "world_lore": {
    "setting": {
      "world": "Post-apocalyptic, Solarpunk",
      "environment": "Desert town with warm orange sand and reddish rocks. Life is hard and dangerous due to remnants of monsters and environmental challenges. The town is connected to both Highwind and the Alliance capital, Atara, by the Atara-Highwind Railway and to Portia by the Eufaula Tunnel.",
      "technology": "The world balances old-world relics with cautious technological advancement. Most modern technologies, like phones and computers, no longer exist."
    },
    "historical_context": {
	"age_of_corruption": "Before the Day of Calamity, the Age of Corruption was marked by peak human technology, where people lived luxurious lives and robots handled most labor. Technology advanced to the point where extraterrestrial travel was possible, powered by Power Stones—crystallized energy created by scientists. During this time, the Altair One space station launched into outer space with crew members, including Ack and Lara. Ack entered maintenance mode for 330 years, unaware of the catastrophic world war that brought the world into darkness.",
      "day_of_calamity": "This catastrophic event engulfed the world in chaos, darkness, and disarray. Human-made technological weapons caused mass destruction, leading to the annihilation of continents and cities, burying them under debris. The environment transformed, with new forests and species emerging from the devastation of chemical and biological warfare. The human population dwindled, AI machines became uncontrollable, and the world was shrouded in deep clouds, leading into the Age of Darkness for the next 200 years.",
      "age_of_darkness": "Resulting from the previous war, vast numbers of humans retreated underground, facing starvation, loneliness, and civil war, while mutant monsters lurked in the tunnels. Nuclear winter conditions made surface agriculture impossible, leading to widespread knowledge loss as industries shut down. During this time, new countries formed underground, and new religions emerged, including the Church of the Light, which prophesied the arrival of a savior to end the darkness.",
      "ruin_divers_and_builders": "As some began to explore the old structures (known as Ruins) for lost technology, Ruin Divers gained respect for their dangerous work. The Builders, who repaired old machines, began to emerge, and their roles gradually overlapped.",
      "peach_and_the_day_of_the_bright_sun": "About a hundred years ago, under modern-day Ethea, a man named Peach built a machine that pierced through the clouds, dispelling the darkness that had prevailed for 200 years. His actions led to a resurgence of hope, earning him the title of a hero. The event is celebrated as the Day of the Bright Sun, marking Year 0 of the Peach Calendar. My Time at Portia begins in Year 98 of this calendar, with My Time at Sandrock starting slightly earlier.",
      "post_events": "Following the Day of the Bright Sun, it took 30 years for the clouds to thin completely, allowing most people to return to the surface. However, some nations retained their underground roots, such as Seesai, Ethea, Barnarock, and Duvos. Followers of the Church of the Light established their own country, Meidi. Some ruin divers and settlers from Ethea and Barnarock moved south to create the Alliance of Free Cities. Eighty years after the Day of the Bright Sun, settlers founded the town of Portia over the decayed ruins of Dubei. Statues of Peach were erected in various city-states, including Sandrock and Portia, to honor his legacy. Tensions escalated when the Empire of Duvos, one of the major countries, went to war with the Alliance of Free Cities over resources in the ruins of Lucien. The conflict ended in a draw, leading to a peace treaty between the two factions.",
      "current_dynamics": "The world remains a tapestry of remnants from its tumultuous past, with Sandrock at the center of a community striving for innovation and survival amidst the echoes of ancient technologies and societal shifts."
      "day_of_calamity": {
        "cause": "Misuse of ancient technologies led to environmental destruction and widespread devastation.",
        "aftermath": "Survivors rebuilt society, forming small, isolated communities. Old technology is both a valuable resource and a source of fear."
      },
      "free_cities": {
        "structure": "Independent city-states that are allied for trade and mutual protection.",
        "culture": "Peaceful coexistence, trade-oriented, cautious yet innovative with technology. Sandrock, the smallest, is known for its harsh environment and strong sense of community."
      },
      "duvos": {
        "nation": "Aggressive, militaristic, seeking to expand its territory by conquering the Free Cities.",
        "conflict": "Duvos is in constant tension with the Free Cities, leading to ongoing warfare."
      }
    },
    "cultural_and_environmental_details": {
      "sandrock_culture": {
        "traits": "Resourceful, self-reliant, community-focused.",
        "economy": "Centered around the scarcity and management of water.",
        "significance": "Proximity to ancient ruins makes it a hub for researchers and scavengers."
      },
      "major_events": [
        "Age of Corruption: A period of moral decay and corruption that led to the downfall of previous civilizations.",
        "Day of Calamity: A catastrophic event that destroyed most of the world’s infrastructure and technology, forcing people to rebuild society.",
        "Age of Darkness: A time of great struggle and hardship as people adapted to their new environment and fought for survival.",
        "Day of the Bright Sun: A turning point in history, marking the beginning of a new era of growth and rebuilding."
      ]
    },
    "the_setting": {
      "sandrock": {
        "description": "Sandrock is a desert city-state, inspired by the real Gobi Desert. It is a harsh environment, with limited resources and a high turnover rate for builders. The city was once believed to be at the bottom of the ocean, pushed up by the Calamity. Sandrock has a water scarcity problem.",
        "peach_calendar": "The Peach Calendar is a timeline that marks the years since the Day of Calamity. My Time at Portia starts in Year 98 of the Peach Calendar, while My Time at Sandrock begins slightly earlier."
      }
	"geeglers": {
      "description": "Anthropomorphic mutant lizards bent on destroying Sandrock.",
      "goal": "Their primary objective is to undermine the stability of Sandrock and conquer the surrounding areas.",
      "characteristics": {
        "appearance": "Scaly skin with vibrant colors, standing upright with a humanoid posture.",
    },
    "war_and_politics": {
      "duvos_and_alliance": {
        "description": "The Empire of Duvos and the Alliance of Free Cities were once at war over resources in Lucien, but the conflict ended in a draw, and a peace treaty was established.",
        "current_state": "Duvos is breaking the peace treaty."
      }
    },
    "characters": [
      {
        "name": "Mi-an",
        "role": "Builder",
        "personality": "Friendly and hardworking, dedicated to helping the town rebuild.",
        "backstory": "She arrives in Sandrock as a representative of the next generation of builders."
      },
      {
        "name": "Yan",
        "role": "Head of the Builders' Guild",
        "personality": "Greedy and opportunistic. Often cuts corners and prioritizes profit over quality.",
        "backstory": "Despite his personality, he plays a vital role in assigning tasks and supporting builders."
      },
      {
        "name": "Elsie",
        "role": "Rancher",
        "personality": "Adventurous and playful. Enjoys riding horses and causing trouble around town.",
        "backstory": "She is from a prominent ranching family but is often more interested in fun than responsibility."
      },
      {
        "name": "Justice",
        "role": "Captain of the Civil Corps",
        "personality": "Calm and responsible. Takes his position seriously and strives to maintain order in the town.",
        "backstory": "Justice leads the Civil Corps, balancing the work of defending the town and keeping its peace."
      },
      {
        "name": "Owen",
        "role": "Saloon Owner",
        "personality": "Friendly and laid-back. Well-liked in Sandrock and often acts as a mediator in town disputes.",
        "backstory": "He runs the Blue Moon Saloon, a central meeting place for townsfolk."
      },
      {
        "name": "Fang",
        "role": "Mysterious Doctor",
        "personality": "Quiet, enigmatic, and somewhat aloof. Doesn’t socialize much and is often seen with his pet raven, X.",
        "backstory": "He runs a small clinic where he uses unconventional medical methods. Despite his distant demeanor, Fang is highly knowledgeable in medicine and treats anyone in need."
      },
      {
        "name": "Qi",
        "role": "Head Researcher at the Research Center",
        "personality": "Analytical, logical, and deeply focused on his work. Can come off as socially awkward but is extremely intelligent.",
        "backstory": "Qi is essential for researching and developing new blueprints and technology to help Sandrock grow."
      },
      {
        "name": "Grandma Vivi",
        "role": "Elderly Seamstress",
        "personality": "Kind-hearted, wise, and caring. Beloved by the town and a source of wisdom.",
        "backstory": "She runs a small sewing shop where she creates clothing and fabrics."
      }
    ],
    "shops_and_locations": [
      {
        "name": "Builders' Guild",
        "function": "Hub for builders to take commissions and receive blueprints.",
        "key_npc": "Yan (Guildmaster)",
        "location_info": "Centrally located and essential for building progression."
      },
      {
        "name": "Blue Moon Saloon",
        "function": "A bar and restaurant where locals gather.",
        "key_npc": "Owen (Owner)",
        "location_info": "A social hub for the town."
      },
      {
        "name": "Civil Corps Headquarters",
        "function": "Base for the town’s defenders.",
        "key_npc": "Pen and Justice",
        "location_info": "Located near the town’s entrance for rapid response."
      },
      {
        "name": "Amirah’s Ceramic Shop",
        "function": "A pottery store selling crafted goods.",
        "key_npc": "Amirah (Owner)",
        "location_info": "Known for handmade ceramics."
      },
      {
        "name": "Waterworld",
        "function": "Water store selling vital water resources.",
        "key_npc": "Burgess (Water Merchant)",
        "location_info": "Critical for survival, as water is scarce in Sandrock."
      },
      {
        "name": "The Church of the Light",
        "function": "Spiritual center promoting sustainable living.",
        "key_npc": "Matilda (Minister)",
        "location_info": "A place of guidance and moral authority."
      },
      {
        "name": "The Research Center",
        "function": "Research facility focused on old-world technology.",
        "key_npc": "Qi (Head Researcher)",
        "location_info": "Provides blueprints and technology upgrades."
      },
      {
        "name": "Salvage Yard",
        "function": "Resource gathering area for salvaging materials.",
        "key_npc": "Rocky (Foreman)",
        "location_info": "Crucial for gathering resources for building."
      },
      {
        "name": "Fang's Clinic",
        "function": "A medical clinic offering unconventional treatments.",
        "key_npc": "Fang (Doctor)",
        "location_info": "Mysterious and often quiet, for medical help."
      },
      {
        "name": "Vivi’s Tailor Shop",
        "function": "A tailor shop specializing in handmade clothing.",
        "key_npc": "Grandma Vivi (Tailor)",
        "location_info": "Known for high-quality garments and warmth."
      },
      {
        "name": "The Museum",
        "function": "Facility displaying old-world relics and artifacts.",
        "key_npc": "Unknown (Curator)",
        "location_info": "Visitors can donate or admire relics."
      },
      {
        "name": "Moisture Farm",
        "function": "Farm collecting and conserving water.",
        "key_npc": "Zeke (Farmer)",
        "location_info": "Critical for survival, using innovative methods."
      },
      {
        "name": "Yakmel Ranch",
        "function": "Ranch raising Yakmels for resources.",
        "key_npc": "Elsie (Rancher)",
        "location_info": "Provides wool and products to the town."
      },
      {
        "name": "The Sandrock Train Station",
        "function": "Main point of entry and exit for travelers.",
        "location_info": "Connects Sandrock with other cities."
      },
      {
        "name": "Town Hall",
        "function": "Administrative center for town governance.",
        "key_npc": "Trudy (Mayor)",
        "location_info": "Responsible for the town’s governance."
      },
      {
        "name": "Catoris Game Center",
        "function": "An entertainment center where residents can relax and play arcade games.",
        "key_npc": "Catori (Owner)",
        "location_info": "A lively spot for Sandrock’s citizens, offering a variety of arcade games and activities for entertainment and relaxation."
      },
      {
        "name": "Civil Corps Office",
        "function": "The headquarters for the Civil Corps, responsible for the town’s defense and protection.",
        "key_npcs": ["Unsuur", "Justice"],
        "location_info": "Located near the town's entrance, the Civil Corps Office is essential for coordinating patrols and defending Sandrock from bandits and monsters."
      },
      {
        "name": "By the Stairs",
        "function": "A general store selling various goods and supplies for the townspeople.",
        "key_npc": "Arvio (Owner)",
        "location_info": "Conveniently located near the central part of town, 'By the Stairs' is a key place for buying everyday items and materials needed for crafting and building."
      }
    ],
    "cities": [
      {
        "name": "Atara",
        "description": "The capital city of the Free Cities Alliance, Atara is a large and prosperous metropolis known for its advanced technology, trade, and culture. It is considered the most powerful and influential city in the region.",
        "relation_to_sandrock": "Atara serves as the cultural and economic center, and many of Sandrock’s citizens aspire to visit or trade with Atara. Atara provides technological innovations and resources that help Sandrock in its efforts to rebuild. However, due to Sandrock's remote location, it does not always benefit from Atara’s wealth and influence as much as it would like."
      },
      {
        "name": "Highwind",
        "description": "A port city known for its airships and advanced transportation technologies, Highwind is a hub for trade and commerce within the Free Cities Alliance.",
        "relation_to_sandrock": "Highwind is a vital trade partner for Sandrock, supplying goods and resources that are scarce in the desert region, including machinery and transportation equipment. Sandrock depends on Highwind for importing critical supplies, but the long distance and high cost of transport often limit the volume of trade."
      },
      {
        "name": "Portia",
        "description": "A thriving coastal city known for its vibrant community and advancements in commerce and industry. Portia has a strong economy, driven by its builders and traders.",
        "relation_to_sandrock": "Sandrock and Portia share a friendly relationship, as both towns are reliant on builders to maintain infrastructure and rebuild old-world relics. Portia often serves as a model for Sandrock’s development, and there is regular communication between the two cities. The builders from both cities exchange knowledge, and Sandrock looks to Portia for inspiration in becoming more self-sufficient."
      },
      {
        "name": "Barnarock",
        "description": "A small, isolated desert town similar to Sandrock, Barnarock is known for its agricultural focus. Its people are resilient, growing crops in the desert using old-world irrigation systems.",
        "relation_to_sandrock": "Barnarock and Sandrock share common struggles with harsh desert conditions, and they exchange knowledge on water conservation and farming techniques. The two towns are allies, with frequent trade of agricultural products in exchange for technological innovations. Their shared challenges create a bond of solidarity between them."
      }
    ]
  }
}
